<script lang="ts">
	import { onMount } from 'svelte';
	import { page } from '$app/state';
	import { liveQuery } from 'dexie';
	import { Pencil, Download } from 'lucide-svelte';
	import { db, type AnimalAgreement } from '$lib/db';
	import { currentFarm } from '$lib/stores';
	import { agreementKinds, moneyLabel } from '$lib/agreements';
	import { toCsv, downloadCsv } from '$lib/reports';
	import PageHeader from '$lib/components/PageHeader.svelte';
	import Notice from '$lib/components/Notice.svelte';
	let agreement = $state<AnimalAgreement | undefined>(); let pending = $state(false); let loading = $state(true); let error = $state('');
	const settlement = $derived(agreement?.settlement);
	onMount(() => {
		if ($currentFarm?.role !== 'admin') { loading = false; return; }
		const subscription = liveQuery(async () => ({ agreement: await db.agreements.get(page.params.id ?? ''), pending: (await db.outbox.toArray()).some((r) => r.collection === 'agreements' && r.record_id === page.params.id) })).subscribe({ next(data) { agreement = data.agreement?.farm === $currentFarm?.id ? data.agreement : undefined; pending = data.pending; loading = false; }, error() { error = 'No se pudo leer este acuerdo.'; loading = false; } });
		return () => subscription.unsubscribe();
	});
	function exportCsv() {
		if (!agreement) return;
		const rows: (string | number | null)[][] = [
			['Acuerdo','Nombre',agreement.title],['Acuerdo','Modalidad',agreementKinds[agreement.kind]],['Acuerdo','Estado',agreement.status === 'settled' ? 'Liquidado' : 'En curso'],
			['Acuerdo','Propietario',agreement.owner_name],['Acuerdo','Responsable',agreement.partner_name],['Acuerdo','Finca de destino',agreement.external_farm],['Acuerdo','Moneda',agreement.currency],
			['Acuerdo','Inicio',agreement.start_date],['Acuerdo','Liquidación',agreement.end_date],['Acuerdo','Porcentaje propietario',agreement.kind === 'pasture' ? '' : agreement.owner_share],['Acuerdo','Condiciones',agreement.notes]
		];
		for (const row of agreement.animals) rows.push([row.tag,'Peso inicial (kg)',row.initial_weight],[row.tag,'Peso final (kg)',row.final_weight],[row.tag,'Precio por kg',row.price_per_kg],[row.tag,'Fecha final',row.final_date]);
		for (const expense of agreement.expenses) rows.push(['Gasto',`${expense.date} · ${expense.concept} · Pagó ${expense.paid_by === 'owner' ? agreement.owner_name : agreement.partner_name} · ${expense.animal ? agreement.animals.find((a) => a.animal === expense.animal)?.tag ?? expense.animal : 'Todo el acuerdo'}`,expense.amount]);
		if (settlement) for (const [key,value] of Object.entries(settlement)) if (typeof value === 'string' && key !== 'kind') rows.push(['Liquidación',labels[key] ?? key,value]);
		downloadCsv(`acuerdo-${agreement.id}.csv`,toCsv(['Sección','Concepto','Valor'],rows));
	}
	const labels: Record<string,string> = { sale_value:'Valor de venta total',initial_value:'Valor inicial del propietario',gain_value:'Valor antes de gastos',expenses:'Gastos pagados del acuerdo',net_gain:'Ganancia neta a repartir',owner_part:'Parte del propietario',partner_part:'Parte del responsable',owner_paid:'Gastos pagados por el propietario',partner_paid:'Gastos pagados por el responsable',owner_total:'Total correspondiente al propietario',partner_total:'Total correspondiente al responsable',partner_reimbursement:'A reembolsar al responsable' };
</script>
<svelte:head><title>{agreement?.title ?? 'Acuerdo'} · Bovinonic</title></svelte:head>
<div class="workspace-page space-y-6">
	<PageHeader title={agreement?.title ?? 'Detalle del acuerdo'} eyebrow="Acuerdos y estadías" backHref="/agreements" backLabel="Todos los acuerdos" />
	<Notice tone="error" message={error} />
	{#if $currentFarm?.role !== 'admin'}<Notice tone="warning" message="Los acuerdos y sus liquidaciones requieren el rol de administrador." />{:else if loading}<p class="empty-state">Cargando acuerdo…</p>{:else if !agreement}<p class="empty-state">Este acuerdo no está disponible. Sincronizá la finca y volvé a intentar.</p>{:else}
	<div class="flex flex-wrap gap-3"><span class="status-pill {agreement.status === 'settled' ? 'historical' : ''}">{agreement.status === 'settled' ? 'Liquidado · Historial protegido' : 'En curso'}</span>{#if pending}<span class="status-pill pending">Pendiente de envío automático</span>{:else}<span class="status-pill">Confirmado por el servidor</span>{/if}</div>
	<div class="flex flex-wrap gap-3">{#if agreement.status === 'active' && !agreement.sale_receipts?.length}<a class="action-button" href="/agreements/{agreement.id}/edit"><Pencil class="h-4 w-4" />Pesos, gastos y liquidación</a>{/if}<button class="quiet-button" type="button" onclick={exportCsv}><Download class="h-4 w-4" />Descargar detalle CSV</button></div>
	<section class="panel space-y-5 p-5 sm:p-6"><h2 class="section-title">{agreementKinds[agreement.kind]}</h2><dl class="grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-3">{#each [{label:'Propietario de los animales',value:agreement.owner_name},{label:'Responsable',value:agreement.partner_name},{label:'Finca de destino',value:agreement.external_farm},{label:'Fecha de entrega',value:agreement.start_date},{label:'Fecha de liquidación',value:agreement.end_date ?? 'En curso'},{label:'Reparto',value:agreement.kind === 'pasture' ? 'Sin reparto del animal' : `${agreement.owner_share} % propietario / ${(100-Number(agreement.owner_share)).toFixed(2)} % responsable`}] as item}<div><dt class="eyebrow">{item.label}</dt><dd class="mt-2 break-words text-sm">{item.value}</dd></div>{/each}</dl>{#if agreement.notes}<p class="whitespace-pre-wrap break-words text-sm leading-6">{agreement.notes}</p>{/if}<p class="field-help">Moneda: {agreement.currency}. Todos los pesos están expresados en kg. Este acuerdo no cambia la propiedad, el lote ni el estado de los animales.</p></section>
	{#if agreement.sale_receipts?.length}<section class="panel space-y-4 p-5"><h2 class="section-title">Ventas y liquidaciones parciales</h2><p class="field-help">Las condiciones originales quedan protegidas. Cada comprobante conserva la liquidación de sus animales; el acuerdo cierra cuando se venden todos.</p>{#each agreement.sale_receipts as receipt}<a class="quiet-button" href="/sales/{receipt.sale}">{receipt.date} · {receipt.animals.length} animales · Ver venta y liquidación</a>{/each}</section>{/if}<a class="action-button" href="/sales/new">Registrar venta</a><section class="panel space-y-5 p-5 sm:p-6"><h2 class="section-title">Animales · {agreement.animals.length}</h2><div class="grid gap-4 md:grid-cols-2">{#each agreement.animals as row}<div class="form-section"><a class="text-sm font-semibold underline" href="/animals/{row.animal}">{row.tag} · {row.name || 'Sin nombre'}</a>{#if agreement.sale_receipts?.some((r) => r.animals.includes(row.animal))}<p class="field-help">Vendido · Liquidación en el comprobante de venta</p>{/if}{#if agreement.kind !== 'pasture'}<dl class="grid grid-cols-2 gap-3 text-sm">{#if agreement.kind === 'weight_gain'}<div><dt class="field-help">Peso de entrega</dt><dd>{row.initial_weight ?? '—'} kg</dd></div>{/if}<div><dt class="field-help">Peso final</dt><dd>{row.final_weight ? `${row.final_weight} kg` : 'Sin registrar'}</dd></div><div><dt class="field-help">Precio por kg</dt><dd>{row.price_per_kg ? moneyLabel(row.price_per_kg,agreement.currency) : 'Sin registrar'}</dd></div><div><dt class="field-help">Fecha final</dt><dd>{row.final_date ?? 'Sin registrar'}</dd></div></dl>{#if settlement?.lines}{@const line = settlement.lines.find((l) => l.animal === row.animal)}{#if line}<p class="notice">{agreement.kind === 'weight_gain' ? `Ganancia de peso: ${line.gain_kg} kg · Valor: ` : 'Valor para el reparto: '}{moneyLabel(line.gain_value,agreement.currency)} · Gastos asignados a este animal: {moneyLabel(line.assigned_expenses,agreement.currency)}</p>{/if}{/if}{/if}</div>{/each}</div></section>
	<section class="panel space-y-5 p-5 sm:p-6"><h2 class="section-title">Gastos originales del acuerdo · {agreement.expenses.length}</h2>{#if agreement.sale_receipts?.length}<p class="field-help">Los gastos agregados después de vender están detallados en sus comprobantes de venta. La liquidación actualizada también los incluye.</p>{/if}<ul class="divide-y">{#each agreement.expenses as expense}<li class="flex flex-wrap items-start justify-between gap-3 py-4"><div class="min-w-0"><p class="break-words text-sm font-semibold">{expense.concept}</p><p class="field-help">{expense.date} · Pagó {expense.paid_by === 'owner' ? agreement.owner_name : agreement.partner_name}</p><p class="field-help">{expense.animal ? agreement.animals.find((a) => a.animal === expense.animal)?.tag : 'Todo el acuerdo'}</p></div><p class="text-sm font-semibold">{moneyLabel(expense.amount,agreement.currency)}</p></li>{:else}<li class="empty-state">Sin gastos registrados.</li>{/each}</ul></section>
	{#if settlement}<section class="panel space-y-5 p-5 sm:p-6"><h2 class="section-title">{pending ? 'Liquidación pendiente de confirmación' : 'Liquidación confirmada'}</h2><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{#each Object.entries(labels).filter(([key]) => key in settlement) as [key,label]}<div class="rounded-xl border bg-[#f5f7ef] p-4"><p class="field-help">{label}</p><p class="mt-2 text-lg font-semibold">{moneyLabel(settlement[key as keyof typeof settlement] as string,agreement.currency)}</p></div>{/each}</div><Notice message={agreement.kind === 'pasture' ? 'Los gastos pagados por el propietario ya están cubiertos. El importe adelantado por el responsable se muestra como reembolso; no hay reparto del valor del animal.' : 'Primero se descuentan los gastos y se reconocen a quien los pagó. Después se reparte el saldo. El total del propietario incluye su valor inicial, el reembolso de sus gastos y su parte; el total del responsable incluye su reembolso y su parte. Estos importes no registran un pago realizado.'} />{#if Number(settlement.net_gain ?? 0) < 0}<Notice tone="warning" message="Este acuerdo se liquidó con saldo negativo, repartido según los porcentajes confirmados." />{/if}</section>{:else}<Notice message={agreement.sale_receipts?.length ? 'El acuerdo tiene ventas parciales. Registrá la venta de los animales restantes para completar su liquidación.' : 'El acuerdo está en curso. Podés registrar una venta o abrir «Pesos, gastos y liquidación» para continuar el seguimiento.'} />{/if}
	{/if}
</div>
